<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import AttachmentList from '../../Components/Ui/AttachmentList.vue'
import de from '../../i18n/de'
import { router, useForm } from '@inertiajs/vue3'
import { ref } from 'vue'

const props = defineProps({ units: Array, educationPlans: Array, filters: Object, materialItems: { type: Array, default: () => [] }, phaseTemplates: Array, lessonTemplates: Array, socialForms: { type: Array, default: () => [] } })
const search = ref(props.filters?.q ?? '')
const editing = ref(null)
const form = useForm({ title: '', keyword: '', notes: '', education_plan_id: null })
const resourceLinksDraft = ref([])
const materialItemsDraft = ref([])
const deletedResourceLinkIds = ref([])
const deletedMaterialItemIds = ref([])
const activeEditTab = ref('metadata')
const templateEditing = ref(null)
const templateForm = useForm({ lesson_template_id: '', title: '', duration_minutes: null, social_form: '', teacher_interaction: '', learner_activity: '', differentiation: '', didactic_comment: '', material: '', media: '' })

function filter() { router.get('/unterrichtseinheiten', { q: search.value }, { preserveState: true, replace: true }) }
function edit(unit) { editing.value = unit; activeEditTab.value = 'metadata'; resourceLinksDraft.value = [...(unit.resource_links ?? [])].map(link => ({ ...link })); materialItemsDraft.value = [...(unit.material_items ?? [])].map(item => ({ ...item })); deletedResourceLinkIds.value = []; deletedMaterialItemIds.value = []; form.defaults({ title: unit.title, keyword: unit.keyword ?? '', notes: unit.notes ?? '', education_plan_id: unit.education_plan_id }); form.reset(); form.clearErrors() }
function save() { form.transform(data => ({ ...data, resource_links: resourceLinksDraft.value, material_items: materialItemsDraft.value, deleted_resource_link_ids: deletedResourceLinkIds.value, deleted_material_item_ids: deletedMaterialItemIds.value })).put(`/unterrichtseinheiten/${editing.value.id}`, { onSuccess: () => { editing.value = null } }) }
function resourceBaseUrl() { return `/jahresplanung/${editing.value.group.id}/eigene-einheiten/${editing.value.id}/anhaenge` }
function libraryAttachUrl() { return `/jahresplanung/${editing.value.group.id}/ressourcen` }
function updateResourceDescription(resource, description) { useForm({ description }).put(`${resourceBaseUrl()}/${resource.id}`, { preserveScroll: true, onSuccess: refreshEditingUnit }) }
function deleteResource(resource) { router.delete(`${resourceBaseUrl()}/${resource.id}`, { preserveScroll: true, onSuccess: refreshEditingUnit }) }
function refreshEditingUnit(response) { const units = response?.props?.units ?? response?.props?.workspace?.units ?? []; const updated = units.find(unit => unit.id === editing.value?.id); if (updated) editing.value = updated }
function remove(unit) { if (window.confirm(de.deleteUnitConfirm)) router.delete(`/unterrichtseinheiten/${unit.id}`) }
function editTemplate(template) { templateEditing.value = template; templateForm.defaults({ lesson_template_id: template.lesson_template_id, title: template.title, duration_minutes: template.duration_minutes, social_form: template.social_form?.name ?? '', teacher_interaction: template.teacher_interaction ?? '', learner_activity: template.learner_activity ?? '', differentiation: template.differentiation ?? '', didactic_comment: template.didactic_comment ?? '', material: template.material ?? '', media: template.media ?? '' }); templateForm.reset(); templateForm.clearErrors() }
function newTemplate() { templateEditing.value = {}; templateForm.reset(); templateForm.clearErrors() }
function saveTemplate() { const url = templateEditing.value.id ? `/unterrichtseinheiten/phasen-vorlagen/${templateEditing.value.id}` : '/unterrichtseinheiten/phasen-vorlagen'; const method = templateEditing.value.id ? 'put' : 'post'; templateForm[method](url, { onSuccess: () => { templateEditing.value = null } }) }
function removeTemplate(template) { if (window.confirm(de.deletePhaseTemplateConfirm)) router.delete(`/unterrichtseinheiten/phasen-vorlagen/${template.id}`) }
</script>

<template>
    <AppShell>
        <div class="container-full px-3 py-4">
            <h1 class="h2">{{ de.teachingUnits }}</h1>
            <p class="text-muted">{{ de.teachingUnitsIntro }}</p>
            <form class="row g-2 mb-3" role="search" @submit.prevent="filter">
                <div class="col-sm-8 col-lg-5"><label class="visually-hidden" for="teaching-unit-search">{{ de.searchUnits }}</label><input id="teaching-unit-search" v-model="search" class="form-control" type="search" :placeholder="de.searchUnits"></div>
                <div class="col-auto"><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search me-1" aria-hidden="true"></i>{{ de.filter }}</button></div>
            </form>
            <div v-if="$page.props.flash?.success" class="alert alert-success">{{ $page.props.flash.success }}</div>
            <div v-if="!units.length" class="alert alert-info">{{ de.noTeachingUnits }}</div>
            <div v-for="unit in units" :key="unit.id" class="card mb-2 planning-card">
                <div class="card-body d-flex justify-content-between gap-3">
                    <div><h2 class="h5 mb-1">{{ unit.title }}</h2><div class="small text-muted">{{ unit.group?.name }} · {{ unit.group?.school_year?.name }} · {{ unit.lessons_count }} {{ de.lessons }}<span v-if="unit.source_curriculum_topic"> · {{ de.sourceCurriculum }}: {{ unit.source_curriculum_topic.title }}</span><span v-if="unit.education_plan"> · {{ unit.education_plan.title }}</span></div></div>
                    <div class="d-flex gap-2 align-items-start"><button class="btn btn-sm btn-outline-primary" type="button" @click="edit(unit)"><i class="bi bi-pencil me-1" aria-hidden="true"></i>{{ de.editUnit }}</button><button class="btn btn-sm btn-outline-danger" type="button" @click="remove(unit)"><i class="bi bi-trash" aria-hidden="true"></i><span class="visually-hidden">{{ de.deleteUnit }}</span></button></div>
                </div>
            </div>
            <section class="mt-5" aria-labelledby="phase-templates-heading">
                <div class="d-flex justify-content-between align-items-center mb-3"><div><h2 id="phase-templates-heading" class="h4 mb-1">{{ de.phaseTemplates }}</h2><p class="text-muted mb-0">{{ de.phaseTemplatesIntro }}</p></div><button class="btn btn-outline-primary" type="button" @click="newTemplate"><i class="bi bi-plus-lg me-1" aria-hidden="true"></i>{{ de.addPhaseTemplate }}</button></div>
                <div v-if="!phaseTemplates.length" class="alert alert-info">{{ de.noPhaseTemplates }}</div>
                <div v-for="template in phaseTemplates" :key="template.id" class="card mb-2 planning-card"><div class="card-body d-flex justify-content-between gap-3"><div><h3 class="h6 mb-1">{{ template.title }}</h3><div class="small text-muted">{{ template.duration_minutes ? `${template.duration_minutes} ${de.minutes}` : de.noDuration }} · {{ de.version }} {{ template.version }}</div></div><div class="d-flex gap-2 align-items-start"><button class="btn btn-sm btn-outline-primary" type="button" @click="editTemplate(template)"><i class="bi bi-pencil me-1" aria-hidden="true"></i>{{ de.editPhaseTemplate }}</button><button class="btn btn-sm btn-outline-danger" type="button" @click="removeTemplate(template)"><i class="bi bi-trash" aria-hidden="true"></i><span class="visually-hidden">{{ de.deletePhaseTemplate }}</span></button></div></div></div>
            </section>
        </div>
        <div v-if="editing" class="roo-modal-backdrop" role="presentation" @click.self="editing = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editUnit"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.editUnit }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="editing = null"></button></div><form @submit.prevent="save"><ul class="nav nav-tabs mb-4"><li class="nav-item"><button class="nav-link" :class="{ active: activeEditTab === 'metadata' }" type="button" @click="activeEditTab = 'metadata'">{{ de.unitEditorMetadata }}</button></li><li class="nav-item"><button class="nav-link" :class="{ active: activeEditTab === 'resources' }" type="button" @click="activeEditTab = 'resources'">{{ de.attachmentsAndMaterials }}</button></li></ul><div v-if="activeEditTab === 'metadata'"><label class="form-label" for="unit-title">{{ de.unitTitle }}</label><input id="unit-title" v-model="form.title" class="form-control" required><label class="form-label mt-3" for="unit-keyword">{{ de.unitKeyword }}</label><input id="unit-keyword" v-model="form.keyword" class="form-control" maxlength="255"><div class="form-text">{{ de.unitKeywordHint }}</div><label class="form-label mt-3" for="unit-plan">{{ de.educationPlan }}</label><select id="unit-plan" v-model="form.education_plan_id" class="form-select"><option :value="null">{{ de.choose }}</option><option v-for="plan in educationPlans" :key="plan.id" :value="plan.id">{{ plan.title }}{{ plan.external_identifier ? ' (' + plan.external_identifier + ')' : '' }}</option></select><label class="form-label mt-3" for="unit-notes">{{ de.notes }}</label><textarea id="unit-notes" v-model="form.notes" class="form-control" rows="5"></textarea></div><AttachmentList v-else :resources="editing.resources?.filter(resource => !resource.lesson_id) ?? []" :resource-links="resourceLinksDraft" :material-items="materialItemsDraft" :material-text="''" :manage="true" :library-attach-url="libraryAttachUrl()" :library-target-type="'unit'" :library-target-id="editing.id" :upload-url="resourceBaseUrl()" :download-base-url="resourceBaseUrl()" @update="updateResourceDescription" @delete="deleteResource" @uploaded="refreshEditingUnit" @update:resource-links="resourceLinksDraft = $event" @update:material-items="materialItemsDraft = $event" @delete:resource-link="deletedResourceLinkIds.push($event.id)" @delete:material-item="deletedMaterialItemIds.push($event.id)" /><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editing = null">{{ de.cancel }}</button><button class="btn btn-primary" type="submit" :disabled="form.processing">{{ de.saveChanges }}</button></div></form></div></div></section></div>
        <div v-if="templateEditing" class="roo-modal-backdrop" role="presentation" @click.self="templateEditing = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="templateEditing.id ? de.editPhaseTemplate : de.addPhaseTemplate"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ templateEditing.id ? de.editPhaseTemplate : de.addPhaseTemplate }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="templateEditing = null"></button></div><form @submit.prevent="saveTemplate"><label class="form-label" for="phase-template-lesson">{{ de.lessonTemplate }}</label><select id="phase-template-lesson" v-model="templateForm.lesson_template_id" class="form-select" required><option value="">{{ de.choose }}</option><option v-for="lessonTemplate in lessonTemplates" :key="lessonTemplate.id" :value="lessonTemplate.id">{{ lessonTemplate.title }}</option></select><label class="form-label mt-3" for="phase-template-title">{{ de.phaseTitle }}</label><input id="phase-template-title" v-model="templateForm.title" class="form-control" required><div class="row g-2"><div class="col-md-6"><label class="form-label mt-3" for="phase-template-duration">{{ de.phaseDuration }}</label><input id="phase-template-duration" v-model="templateForm.duration_minutes" class="form-control" type="number" min="1" max="999"></div><div class="col-md-6"><label class="form-label mt-3" for="phase-template-social-form">{{ de.socialForm }}</label><input id="phase-template-social-form" v-model="templateForm.social_form" class="form-control" list="template-social-forms" :placeholder="de.socialFormPlaceholder"><datalist id="template-social-forms"><option v-for="socialForm in socialForms" :key="socialForm.id" :value="socialForm.name"></option></datalist></div></div><div class="row g-2"><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-teacher-interaction">{{ de.teacherInteraction }}</label><textarea id="phase-template-teacher-interaction" v-model="templateForm.teacher_interaction" class="form-control" rows="3"></textarea></div><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-learner-activity">{{ de.learnerActivity }}</label><textarea id="phase-template-learner-activity" v-model="templateForm.learner_activity" class="form-control" rows="3"></textarea></div><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-differentiation">{{ de.differentiation }}</label><textarea id="phase-template-differentiation" v-model="templateForm.differentiation" class="form-control" rows="3"></textarea></div><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-didactic-comment">{{ de.didacticComment }}</label><textarea id="phase-template-didactic-comment" v-model="templateForm.didactic_comment" class="form-control" rows="3"></textarea></div><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-material">{{ de.materials }}</label><textarea id="phase-template-material" v-model="templateForm.material" class="form-control" rows="3"></textarea></div><div class="col-lg-6"><label class="form-label mt-3" for="phase-template-media">{{ de.media }}</label><textarea id="phase-template-media" v-model="templateForm.media" class="form-control" rows="3"></textarea></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="templateEditing = null">{{ de.cancel }}</button><button class="btn btn-primary" type="submit" :disabled="templateForm.processing">{{ de.saveChanges }}</button></div></form></div></div></section></div>
    </AppShell>
</template>
